    22	// The callback style is the point: Chapter 5 migrates the service layer off it.
    23	
    24	const tables = {
    25	  users: [
    26	    { id: 1, email: 'ada@example.com', name: 'Ada', deleted_at: null },
    27	    { id: 2, email: 'grace@example.com', name: 'Grace', deleted_at: null },
    28	    { id: 3, email: 'alan@example.com', name: 'Alan', deleted_at: '2026-01-04' },
