    32	    { id: 11, user_id: 1, total_cents: 1350, status: 'quote', deleted_at: null },
    33	    { id: 12, user_id: 2, total_cents: 9900, status: 'paid', deleted_at: null },
    34	    { id: 13, user_id: 3, total_cents: 500, status: 'paid', deleted_at: null },
    35	  ],
    36	  payments: [
    37	    { id: 100, order_id: 10, amount_cents: 4200, captured: true },
    38	    { id: 101, order_id: 12, amount_cents: 9900, captured: false },
    39	  ],
    40	};
    41	
    42	export function reset() {
    43	  tables.users[2].deleted_at = '2026-01-04';
    44	  tables.orders.forEach((o) => { o.deleted_at = null; });
    45	}
    46	
    47	// Old-style callback query. Accepts a table name and a predicate.
    48	export function query(table, predicate, callback) {
    49	  setImmediate(() => {
    50	    const rows = tables[table];
    51	    if (!rows) return callback(new Error(`no such table: ${table}`));
    52	    try {
    53	      callback(null, rows.filter(predicate).map((r) => ({ ...r })));
    54	    } catch (err) {
    55	      callback(err);
    56	    }
    57	  });
    58	}
    59	
    60	export function update(table, id, patch, callback) {
    61	  setImmediate(() => {
    62	    const row = (tables[table] || []).find((r) => r.id === id);
    63	    if (!row) return callback(new Error(`no row ${id} in ${table}`));
    64	    Object.assign(row, patch);
    65	    callback(null, { ...row });
    66	  });
    67	}
