    75	    "node": ">=20"
    76	  },
    77	  "scripts": {
    78	    "test": "node --test",
    79	    "test:module": "node --test",
    80	    "lint": "node scripts/lint.js",
    81	    "format": "node scripts/lint.js --fix"
    82	  }
    83	}
    84	#!/usr/bin/env node
    85	// A dependency-free stand-in for eslint and prettier, so the Chapter 6 hooks
    86	// have something real to run on a machine with no npm install.
    87	// Checks: no tab indentation, no trailing whitespace, file ends in one newline.
    88	import { readdirSync, readFileSync, writeFileSync, statSync } from 'node:fs';
    89	import { join } from 'node:path';
    90	
    91	const fix = process.argv.includes('--fix');
    92	const targets = process.argv.slice(2).filter((a) => !a.startsWith('--'));
    93	
    94	function walk(dir) {
    95	  return readdirSync(dir).flatMap((e) => {
    96	    const p = join(dir, e);
    97	    if (statSync(p).isDirectory()) return walk(p);
    98	    return p.endsWith('.js') ? [p] : [];
    99	  });
   100	}
   101	
   102	const files = targets.length ? targets : [...walk('src'), ...walk('tests')];
   103	let problems = 0;
   104	
   105	for (const f of files) {
   106	  const before = readFileSync(f, 'utf8');
   107	  let after = before.replace(/\t/g, '  ').replace(/[ \t]+$/gm, '');
   108	  if (!after.endsWith('\n')) after += '\n';
   109	  after = after.replace(/\n{3,}$/, '\n');
   110	  if (after !== before) {
   111	    if (fix) writeFileSync(f, after);
   112	    else { console.error(`${f}: formatting`); problems += 1; }
   113	  }
   114	}
   115	
   116	if (problems && !fix) {
   117	  console.error(`${problems} file(s) need formatting. Run: npm run format`);
   118	  process.exit(1);
   119	}
   120	console.log(fix ? `formatted ${files.length} file(s)` : `${files.length} file(s) clean`);
.
