// the reader adds, which is the part of the exercise with no worked answer.

// query() runs its callback inside a try/catch and re-invokes it with the error
// if it throws, so a throwing caller would be called twice. Deferring the call
// moves it outside that try, so the caller is called exactly once.
function deliver(callback) {
  return (err, result) => process.nextTick(callback, err, result);
}

export function findPaymentsForOrder(orderId, callback) {
  query('payments', (p) => p.order_id === orderId, deliver(callback));
}

export function uncapturedTotalCents(callback) {
  const done = deliver(callback);
  query('payments', (p) => p.captured === false, (err, rows) => {
    if (err) return done(err);
    done(null, rows.reduce((sum, p) => sum + p.amount_cents, 0));
  });
}

